css:
/* T3 Codex: the Codex app look for T3 Code. github.com/HarjjotSinghh/t3-codex */

:root {
  --t3x-font: -apple-system, BlinkMacSystemFont, "SF Pro Text", ui-sans-serif, system-ui, "Segoe UI", Helvetica, Arial, sans-serif;
  --t3x-mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace;
  --t3x-link: #2562a2;
  --t3x-indigo: #3083d8;
  --t3x-composer: #ffffff;
  --t3x-composer-border: #efefef;
  --t3x-inline-code: #ececeb;
  --t3x-pill: #ededec;
  --t3x-popover-border: #e8e8e7;
  --t3x-shadow: 0 8px 28px rgba(0, 0, 0, 0.08), 0 1px 3px rgba(0, 0, 0, 0.04);
}
.dark {
  --t3x-link: #b0b5e6;
  --t3x-indigo: #606acc;
  --t3x-composer: #262729;
  --t3x-composer-border: transparent;
  --t3x-inline-code: #242427;
  --t3x-pill: #313234;
  --t3x-popover-border: #2a2a2c;
  --t3x-shadow: 0 10px 32px rgba(0, 0, 0, 0.45);
}

/* Type */
body, [data-slot="sidebar"], [data-workspace-area="conversation"], .composer-tiptap, [data-slot="menu-popup"], [data-slot="popover-popup"], [data-slot="dialog-popup"] {
  font-family: var(--t3x-font) !important;
  -webkit-font-smoothing: antialiased;
  letter-spacing: -0.003em;
}
code, pre, kbd, .chat-markdown-codeblock, .chat-markdown code { font-family: var(--t3x-mono) !important; }

/* Sidebar: flat, quiet rows with soft rounded highlight */
[data-slot="sidebar-inner"], [data-slot="sidebar"] :has(> [data-slot="sidebar-inner"]) { border-right-color: transparent !important; border-left-color: transparent !important; }
[data-thread-item] { border-radius: 10px !important; }
[data-slot="project-monogram"] svg { border-radius: 8px; }

/* Chat header: Codex's title bar sits on the chrome color */
[data-chat-header] { background: #f7f7f7 !important; border-bottom-color: transparent !important; box-shadow: none !important; }
.dark [data-chat-header] { background: #1c1c1d !important; }

/* User message: soft bubble, big radius, no border */
[data-user-message-bubble] {
  border-radius: 20px !important;
  border: 0 !important;
  box-shadow: none !important;
  padding: 10px 16px !important;
}

/* Assistant text */
.chat-markdown { line-height: 1.7 !important; }
.chat-markdown a { color: var(--t3x-link) !important; text-decoration: none !important; }
.chat-markdown a:hover { text-decoration: underline !important; }
.chat-markdown :not(pre) > code {
  background: var(--t3x-inline-code) !important;
  border: 0 !important;
  border-radius: 6px !important;
  padding: 0.1em 0.35em !important;
  font-size: 0.92em !important;
}
.chat-markdown-codeblock {
  border-radius: 16px !important;
  border: 0 !important;
  overflow: hidden;
}

/* Composer: big rounded card, no hard border in dark */
[data-slot="composer-host"] {
  border-radius: 24px !important;
  background: var(--t3x-composer) !important;
  border: 1px solid var(--t3x-composer-border) !important;
  box-shadow: none !important;
}
[data-slot="composer-host"]:focus-within { border-color: var(--t3x-composer-border) !important; box-shadow: none !important; outline: none !important; }
[data-slot="composer-host"]::before, [data-slot="composer-host"]::after { border-radius: 24px !important; }
[data-slot="composer-host"]::before { background-color: var(--t3x-composer) !important; border-color: transparent !important; box-shadow: none !important; }
/* the visible card is the wrapper around composer-host */
[data-chat-composer-form] :has(> [data-slot="composer-host"]) { border-radius: 24px !important; box-shadow: none !important; }
[data-chat-composer-form] :has(> [data-slot="composer-host"])::before,
[data-chat-composer-form] :has(> [data-slot="composer-host"])::after { border-radius: 24px !important; }
.dark [data-chat-composer-form] :has(> [data-slot="composer-host"]) { background: transparent !important; }
[data-chat-composer-form] [data-slot="button"], [data-chat-composer-form] [data-slot="select-trigger"] { border-radius: 999px !important; }

/* Popovers, menus, dialogs */
[data-slot="menu-popup"], [data-slot="popover-popup"] {
  border-radius: 16px !important;
  border: 1px solid var(--t3x-popover-border) !important;
  box-shadow: var(--t3x-shadow) !important;
}
[data-slot="dialog-popup"] { border-radius: 20px !important; border: 1px solid var(--t3x-popover-border) !important; }
[data-slot="tooltip-popup"] { border-radius: 8px !important; }
[data-slot="menu-popup"] [role="menuitem"], [data-slot="menu-popup"] [role="menuitemradio"], [data-slot="menu-popup"] [role="option"] { border-radius: 10px !important; }

/* Controls */
[data-slot="button"] { border-radius: 10px; }
[data-slot="input"], [data-slot="select-trigger"] { border-radius: 10px !important; }
[data-slot="switch"][data-checked], [data-slot="switch"][aria-checked="true"] { background: var(--t3x-indigo) !important; }

/* Icons: Codex uses thin strokes */
svg.lucide { stroke-width: 1.6; }

/* Scrollbars */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: rgba(127, 127, 127, 0.22); border-radius: 8px; }
[data-slot="scroll-area-thumb"] { background: rgba(127, 127, 127, 0.28) !important; }

::selection { background: color-mix(in srgb, var(--t3x-indigo) 35%, transparent); }
